struct Account { std::mutex mtx; long balance; };

// ❌ 데드락 위험: from 먼저, to 나중 순서로 잠금
void transfer(Account& from, Account& to, long amt) {
    std::lock_guard<std::mutex> lk1(from.mtx);   // ① from 잠금
    std::lock_guard<std::mutex> lk2(to.mtx);     // ② to 잠금
    from.balance -= amt; to.balance += amt;
}

// 스레드1: transfer(A, B)  → A 잠금 후 B 기다림
// 스레드2: transfer(B, A)  → B 잠금 후 A 기다림
// 둘이 동시에 실행되면 → 서로 상대를 기다림 = 데드락 💀

// ✅ 순서 통일: '주소가 작은' 락부터 — 모든 스레드가 동일 순서 → 순환 불가
void transfer(Account& from, Account& to, long amt) {
    Account* a = &from;
    Account* b = &to;
    if (a > b) std::swap(a, b);          // 주소 기준 정렬(핵심!)
    std::lock_guard<std::mutex> lk1(a->mtx);  // 항상 작은 주소 먼저
    std::lock_guard<std::mutex> lk2(b->mtx);  // 그다음 큰 주소
    from.balance -= amt; to.balance += amt;
}

// transfer(A,B) 든 transfer(B,A) 든 → 둘 다 min→max 순서로 잠금
// → '엇갈림'이 사라져 순환이 물리적으로 불가능

// ✅ 가장 쉬운 길: 둘을 한꺼번에 잠금(데드락 회피 내장)
void transfer(Account& from, Account& to, long amt) {
    std::scoped_lock lk(from.mtx, to.mtx);   // C++17
    from.balance -= amt; to.balance += amt;
}
// 원리: '하나 쥔 채 다른 걸 무한정 기다리지' 않아.
// 다 못 잡으면 쥔 것도 풀고 재시도 → 순환이 안 생김.
